    public static function get_icon( string $icon ): string
    {
        $icons = [
            'search' => 'search',
            'settings' => 'settings',
            'mail' => 'mail',
        ];

        $icon = strtolower(trim($icon));

        if (!isset($icons[$icon])) {
            return '';
        }

        return self::{$icons[$icon]}();
    }
